import json,html,hashlib
from pathlib import Path
p=Path(__file__).resolve().parents[1]
pack=json.loads((p/'content/grub/uk-core-drafts-20261017.json').read_text())
evidence=json.loads((p/'evidence/grub-expansion-closeout-2026-09-16/uk-editorial-decisions-20261017.json').read_text())
esc=lambda x:html.escape(str(x))
parts=['<!doctype html><html lang="en-GB"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Grub UK catalogue — recipe review</title><style>body{overflow-wrap:anywhere;box-sizing:border-box;font:16px/1.55 system-ui,sans-serif;background:#e7e3da;color:#050505;margin:auto;padding:24px;max-width:1050px}header,article,section{background:#fff;padding:24px;margin:18px 0;border-radius:10px}h1,h2{line-height:1.2}h2{border-top:5px solid #707762;padding-top:14px}a{color:#405139}table{border-collapse:collapse;width:100%;font-size:14px}td,th{overflow-wrap:anywhere;border:1px solid #c4c9bb;text-align:left;padding:9px;vertical-align:top}li{margin:8px 0}code{overflow-wrap:anywhere;font-size:12px}.hold{background:#fff2df;padding:16px;border-left:5px solid #a16424}.muted{color:#505747}details{margin:15px 0}summary{font-weight:700;cursor:pointer}@media(max-width:600px){body{padding:10px}header,article,section{padding:16px}table{font-size:12px}td,th{padding:6px}}@media print{body{background:#fff;font-size:11px}article{break-before:page}details{display:block}details>*{display:block}a{color:#050505}}</style><header><h1>Grub UK catalogue — exact recipe review</h1><p class="hold"><strong>Prepared correction — not deployed.</strong> The new food below is unpublished. No independent human editorial acceptance or physical cooking trial is claimed. Deployment permission is already held; it does not substitute for the required review.</p><p>This pack contains the actual new recipes and the unchanged existing dishes proposed for the core. The complete per-published-recipe disposition remains in the existing catalogue evidence. It is not another action tracker.</p><p><strong>Review basis:</strong> familiar UK food; sensible portions and combinations; honest hands-on and elapsed times; ordinary equipment; manageable ingredients; useful leftovers and minimal waste. The Eatwell Guide assesses balance across a day or week, rather than using calories or protein alone.</p><p><strong>Required independent human review:</strong> title, ingredients, method, equipment, allergens, nutrition, storage, food safety, serving metadata and practical appeal. Record reviewer identity, date, exact candidate hash and any changes or unresolved findings. AI author checks and a human reading are distinct from a physical cooking trial.</p><p>Four pizzas lead the proposed pizza search in this order: Margherita; pepperoni; ham and pineapple; mushroom. They use actual mozzarella and the stated toppings, with half a pizza and salad per person. Meat toppings are optional choices rather than the daily default.</p></header>']
review=json.loads((p/'evidence/grub-expansion-closeout-2026-09-16/uk-exact-author-check-20261017.json').read_text())
parts.append('<section><h2>AI author checks — human review still required</h2><p>All 84 nutrient calculations across the 14 new recipes were recomputed; 186 CoFID source values match the official workbook. This verifies arithmetic and source transcription, not taste, portion satisfaction or cooking times.</p><h3>Corrections in this version</h3><ul>'+''.join('<li>'+esc(x)+'</li>' for x in review['fixed'])+'</ul><h3>Points for the human reviewer</h3><ul>'+''.join('<li>'+esc(x)+'</li>' for x in review['existing_review_attention'])+'<li>The chickpea curry uses generic curry paste: assess the exact jar, allergens, vegetarian suitability and cooking instructions. Its mustard headline does not establish allergy suitability.</li></ul><p>Only the two jacket recipes and lentil pasta have changed candidate hashes. The other 11 new recipes and all 32 existing recipe bodies remain unchanged.</p></section>')
parts.append('<section><h2>New recipes</h2><ol>'+''.join('<li><a href="#'+esc(r['id'])+'">'+esc(r['title'])+'</a></li>' for r in pack['candidates'])+'</ol><p>All timings below are author estimates, not kitchen-tested promises. No illustrative images are attached to these drafts.</p></section>')
def card(r,new=True):
 d=r['data'] if new else {**r['evidence'],'hands_on_minutes':r.get('hands_on_minutes')}; title=r['title']; nutrition=d.get('nutrition',{})
 h='<article id="'+esc(r['id'])+'"><h2>'+esc(title)+'</h2><p><strong>'+('UNPUBLISHED DRAFT' if new else 'Existing recipe proposed for discovery retention — content unchanged')+'</strong></p>'
 h+='<p>Serves '+esc(d.get('servings'))+' · preparation '+esc(d.get('prep_minutes'))+' min · cooking '+esc(d.get('cook_minutes'))+' min'
 if d.get('hands_on_minutes') is not None:h+=' · hands-on about '+esc(d.get('hands_on_minutes'))+' min'
 h+=' · total '+esc(d.get('total_minutes') if d.get('total_minutes') is not None else (d.get('prep_minutes') or 0)+(d.get('cook_minutes') or 0))+' min.</p>'
 if not new:h+='<p class="muted">The hands-on figure is an editorial estimate from the actual method, not a physical timing trial. Longer dishes stay among optional cooking choices.</p>'
 h+='<h3>Ingredients — full recipe</h3><ul>'+''.join('<li>'+esc(i['amount'])+' '+esc(i.get('unit',''))+' '+esc(i['item'])+'</li>' for i in d['ingredients'])+'</ul>'
 h+='<h3>Method</h3><ol>'+''.join('<li>'+esc(s)+'</li>' for s in d['method'])+'</ol>'
 h+='<p><strong>Equipment:</strong> '+esc(', '.join(d.get('equipment') or []))+'</p><p><strong>Allergens:</strong> '+esc(', '.join(d.get('allergens') or []) or 'None specifically listed; check every product label.')+'</p>'
 h+='<h3>Food safety</h3><ul>'+''.join('<li>'+esc(x)+'</li>' for x in d.get('food_safety',[]))+'</ul>'
 h+='<h3>Storage and leftovers</h3>'+''.join('<p><strong>'+esc(k)+':</strong> '+esc(v)+'</p>' for k,v in (d.get('storage') or {}).items())
 for key in ['leftovers_note','substitutions','editorial_note','allergen_note','timing_note']:
  if d.get(key):h+='<p>'+esc(d[key])+'</p>'
 h+='<h3>Estimated nutrition — per serving</h3><table><tr>'+''.join('<th>'+esc(k.replace('_g',' (g)'))+'</th>' for k in ['kcal','protein_g','carbohydrate_g','fat_g','fibre_g','saturates_g'])+'</tr><tr>'+''.join('<td>'+esc(nutrition.get(k) if nutrition.get(k) is not None else 'Not established')+'</td>' for k in ['kcal','protein_g','carbohydrate_g','fat_g','fibre_g','saturates_g'])+'</tr></table>'
 if new:
  if d.get('nutrition_limitations'):h+='<p class="muted">'+esc(' '.join(d['nutrition_limitations']))+'</p>'
  h+='<p>'+esc(nutrition['methodology'])+'</p>'
  if nutrition['unknown_nutrients']:h+='<p class="hold">Unestablished source values: '+esc(nutrition['unknown_nutrients'])+'. These have not been replaced with zero.</p>'
  h+='<details><summary>Ingredient nutrition sources and limitations</summary><ul>'
  for e in d['ingredient_evidence']:h+='<li><strong>'+esc(e['item'])+':</strong> '+esc(e['source_food_name'])+'; '+esc(e['calculation_grams'])+' g in the whole recipe. '+esc(e['limitations'])+' <a href="'+esc(e['source'] if e['source'].startswith('http') else pack['sources'][3])+'">Source</a></li>'
  h+='</ul></details><p><strong>Exact candidate:</strong> <code>'+esc(r['content_hash'])+'</code></p><p class="hold">Independent review: pending. Human second-person review: pending. Physical cooking trial: not performed. Publication: held.</p>'
 else:h+='<p>'+esc(r['reason'])+'</p>'
 return h+'</article>'
for r in pack['candidates']:parts.append(card(r))
parts.append('<section><h2>Existing dishes proposed for retention</h2><p>These dishes keep their existing identities and original publication evidence. No new recipe authorship, human acceptance or cooking trial is claimed. Old recipes outside discovery remain addressable through saved meals, plans and shopping references.</p></section>')
for r in evidence['current_recipes']:
 if r['discovery_eligible']:parts.append(card(r,False))
parts.append('<section><h2>Sources and evidence</h2><ul>'+''.join('<li><a href="'+esc(x)+'">'+esc(x)+'</a></li>' for x in pack['sources'])+'</ul><p>Official CoFID workbook SHA256: <code>'+esc(pack['workbook_sha256'])+'</code></p><p>Existing catalogue evidence: evidence/grub-expansion-closeout-2026-09-16/uk-editorial-decisions-20261017.json. Every published identity has a disposition; withdrawn descendants have conservative screening decisions rather than invented individual culinary or human acceptance.</p><p>Coverage: 2,691 published records including source additions; 2,678 current governed recipe references. Current recipes: 32 retain; 540 correct; 102 replace; 2,004 withdraw. These figures are evidence coverage, not completion or a recipe-count target.</p><p>No homepage change, account data write, cost, external communication or production deployment was performed for this correction.</p></section></html>')
out=p/'evidence/grub-expansion-closeout-2026-09-16/Grub-UK-Recipe-Review-20261017.html';out.write_text('\n'.join(parts))
assert out.read_text().count('<article ')==46
assert all(r['content_hash'] in out.read_text() for r in pack['candidates'])
print(json.dumps({'file':str(out),'bytes':out.stat().st_size,'sha256':hashlib.sha256(out.read_bytes()).hexdigest(),'newRecipes':14,'existingRecipes':32,'publication':'pending'}))
